(()=>{
 const E=Engineering,axisUnit=()=>taggedVector('u','axis','axisMomentUnit'),axisScalar=()=>symbolMarkup('Maxis','axisMomentScalar','<msub><mi>M</mi><mtext>axis</mtext></msub>'),pointM=()=>taggedVector('M','A','axisPointMoment'),axisR=()=>taggedVector('r','AP','axisMomentPosition'),coupleM=()=>taggedVector('M','c','coupleVector'),separation=()=>taggedVector('r','QP','coupleSeparation'),force=()=>vector('F','coupleForce'),arm=()=>mi('d','coupleArm');
 E.symbols({
  axisMomentScalar:['Maxis · signed moment about the axis','A scalar, in N·m, equal to uaxis · MA. It measures the twisting tendency about the chosen positive axis. A positive value follows the right-hand rule about +uaxis; a negative value twists the other way. If asked for magnitude only, report |Maxis|.'],
  axisMomentUnit:['uaxis · positive-axis unit vector','A dimensionless vector of magnitude 1 along the selected positive axis. For A→B, form (B − A)/|B − A|. Reversing the positive direction changes the sign of the scalar axis moment but not its magnitude. A and B must be distinct.'],
  axisPointMoment:['MA · full moment about a point on the axis','The full Cartesian moment vector about A, in N·m. A must lie on the specified axis. Project this moment onto the axis to get the signed axis moment. Its total magnitude is generally different from the axis moment magnitude. Moving the reference point along the same axis preserves the scalar projection.'],
  axisMomentPosition:['rAP · axis-moment position vector','The displacement P − A, in metres, from a reference point A on the specified axis to a point P on the force line. The required scalar is uaxis · (rAP × F). Do not use a reference point off the axis without translating the moment.'],
  axisMomentParallel:['M∥ · axial moment vector','The vector Maxis uaxis, in N·m. It is the part of the full moment parallel to the axis. It stays unchanged when you reverse the positive-axis convention, even though the signed scalar changes.'],
  tripleProduct:['u · (r × F) · scalar triple product','First calculate the moment vector r × F, then take its dot product with the axis unit vector u. The final result is a scalar in N·m. Cross-product order matters. This operation combines moment calculation with projection.'],
  coupleVector:['Mc · couple moment vector','The net moment of two equal, opposite, parallel forces on different lines, in N·m. With +F at P and −F at Q, Mc = (P − Q) × F. This is a free vector: for a rigid body, its value is independent of which reference point you use to sum the two moments.'],
  coupleSeparation:['rQP · separation from −F to +F','The displacement P − Q, in metres, from the point where −F acts to the point where +F acts. Use this vector with +F in rQP × F. Reversing the separation alone reverses the calculated couple moment.'],
  coupleForce:['F · positive force of the pair','The force vector at P, in N. The force at Q is exactly −F: same magnitude, opposite direction, and parallel. Together they have zero resultant force. Their separation can create a nonzero moment.'],
  coupleArm:['d · perpendicular spacing of force lines','The shortest distance between the two parallel force lines, in metres. It is not generally the point-to-point separation |P − Q|. For nonzero F, d = |Mc|/|F|, and the couple moment magnitude is |F|d.'],
  coupleReference:['O · moment-sum reference point','Any chosen point used to calculate the two individual moments. Changing O changes the separate moments but not their sum when the two forces are equal and opposite. O does not have to lie on either force line.'],
  coupleResultant:['R · resultant force vector of the pair','The vector sum +F + (−F), in N. For this exact force pair it is the zero vector. The zero net force does not cancel the couple moment when the two parallel lines are separated.'],
  couplePositiveMoment:['MO,+F · moment of the positive force about O','The individual moment (P − O) × F, in N·m. It depends on the chosen reference point O. Add it to the moment of −F at Q to obtain the reference-independent couple moment.'],
  coupleNegativeMoment:['MO,−F · moment of the negative force about O','The individual moment (Q − O) × (−F), in N·m. This term depends on O, but its sum with the positive-force moment does not.'],
  couplePointP:['P · point carrying +F','The position of the positive force, in metres. In rQP = P − Q, this is the ending point of the separation vector.'],
  couplePointQ:['Q · point carrying −F','The position of the exactly opposite force, in metres. In rQP = P − Q, this is the starting point.'],
  axisMx:['Mx · x component of moment about A','The signed x component of the full moment about point A, in N·m. It is a moment about the Cartesian x axis through A, not automatically the moment about rod AB.'],
  axisMy:['My · y component of moment about A','The signed y component of the full moment about A, in N·m. It must be combined with the axis unit vector’s y component in the scalar projection.'],
  axisMz:['Mz · z component of moment about A','The signed z component of the full moment about A, in N·m. If AB is the +z axis, this component is also the signed axis moment.']
 },{
  axisMoment:()=>axisScalar()+mo('=')+axisUnit()+mo('·')+pointM()+mo('=')+axisUnit()+mo('·')+mo('(')+axisR()+mo('×')+vector('F','forceMoment')+mo(')'),
  coupleMoment:()=>coupleM()+mo('=')+separation()+mo('×')+force(),
  coupleMagnitude:()=>mo('|')+coupleM()+mo('|')+mo('=')+mo('|')+force()+mo('|')+arm()
 },[
  {title:'Find a moment about a specified axis',body:'axisMoment',use:'Find the <strong>signed twisting moment about a rod or specified axis</strong>, rather than the whole moment vector.',need:'Two <strong>distinct points on the axis</strong> and a <strong>moment vector about a point on that axis</strong>; or a force and its application point to calculate that moment first.',condition:'Normalize the axis. The reference point for the moment must <strong>lie on the axis</strong>. Use <strong>u · (r × F)</strong> and preserve the sign. For magnitude only, take the absolute value.',example:'MA = <strong>(0, 180, 0) N·m</strong> and positive axis direction <strong>(3, 4, 0)</strong> give u = <strong>(0.6, 0.8, 0)</strong> and Maxis = <strong>144 N·m</strong>.',symbols:['axisMomentScalar','axisMomentUnit','axisPointMoment','axisMomentPosition','tripleProduct']},
  {title:'Calculate a couple moment',body:'coupleMoment',use:'Find the <strong>net turning effect of an equal and opposite force pair</strong>.',need:'The force vector <strong>+F at P</strong>, the exactly opposite force <strong>−F at Q</strong>, and their <strong>application-point coordinates</strong>.',condition:'Forces must have <strong>equal magnitude, opposite directions, and parallel lines</strong>. Noncoincident lines produce a nonzero couple. Use <strong>P − Q with +F</strong>; the net force is zero. The couple moment is <strong>independent of reference point</strong>.',example:'+F = <strong>(0, 100, 0) N</strong> at P = <strong>(2, 0, 0) m</strong> and −F at Q = <strong>(0, 0, 0) m</strong> give Mc = <strong>(0, 0, 200) N·m</strong>.',symbols:['coupleVector','coupleSeparation','coupleForce','coupleReference']},
  {title:'Use a couple’s perpendicular spacing',body:'coupleMagnitude',use:'Calculate the <strong>magnitude</strong> of a couple from the common force magnitude and line spacing.',need:'The magnitude of <strong>one force (N)</strong> and the <strong>perpendicular spacing d (m)</strong> between force lines.',condition:'Use <strong>perpendicular spacing</strong>, not automatically the distance between the application points. Do not double F: <strong>|Mc| = Fd</strong>. Determine direction separately with the right-hand rule.',example:'Two equal and opposite <strong>100 N</strong> forces spaced <strong>2 m</strong> apart give a couple magnitude of <strong>200 N·m</strong>.',symbols:['coupleVector','coupleForce','coupleArm']}
 ]);
 $('axisCouple').innerHTML=`<div class="lesson-strip"><span class="number">05</span><div><h2>Twist about an axis. Understand a force couple.</h2><p>Two related ideas, with different inputs and conditions.</p></div></div><div class="projection-choices" role="group" aria-label="Lesson selection"><button id="axisLessonButton" aria-pressed="true">Moment about an axis</button><button id="coupleLessonButton" aria-pressed="false">Couple moments</button></div><section id="axisLesson"></section><section id="coupleLesson" hidden></section>`;
 $('axisLessonButton').onclick=()=>{$('axisLesson').hidden=false;$('coupleLesson').hidden=true;$('axisLessonButton').setAttribute('aria-pressed','true');$('coupleLessonButton').setAttribute('aria-pressed','false');};$('coupleLessonButton').onclick=()=>{$('axisLesson').hidden=true;$('coupleLesson').hidden=false;$('axisLessonButton').setAttribute('aria-pressed','false');$('coupleLessonButton').setAttribute('aria-pressed','true');};
 let axisState={A:[0,0,0],B:[3,4,0],M:[0,180,0],P:[2,1,0],F:[0,100,0],reverse:false,source:'given',view:'iso'};
 const viewSelect=id=>`<label>Diagram view<select id="${id}"><option value="iso">3D projection</option><option value="xy">xy projection</option><option value="xz">xz projection</option><option value="yz">yz projection</option></select></label>`;
 $('axisLesson').innerHTML=`<div class="lab-grid"><article class="panel"><div class="panel-heading"><h3>Axis moment lab</h3><span class="live">● LIVE</span></div><p id="axisProblem" class="position-problem"></p><label>Starting information<select id="axisSource"><option value="given">Given moment vector about A</option><option value="force">Force at point P</option></select></label>${viewSelect('axisView')}<svg id="axisDiagram" viewBox="0 0 600 400" role="img" aria-label="Specified axis, full moment direction and axial component"></svg><p class="projection-note">Point geometry uses a common metre scale. Force and moment arrows indicate direction with illustrative lengths; projected screen measurements are not 3D measurements.</p><div class="coordinate-controls">${E.fields('axisA','Point A on axis','m',axisState.A)}${E.fields('axisB','Point B on axis','m',axisState.B)}</div><div id="axisGivenInputs">${E.fields('axisM','Moment about A','N·m',axisState.M)}</div><div id="axisForceInputs" hidden><div class="coordinate-controls">${E.fields('axisP','Force application point P','m',axisState.P)}${E.fields('axisF','Applied force','N',axisState.F)}</div></div><div class="actions moment-actions"><button id="axisReverse">Reverse positive axis</button><button id="axisForceExample">Force-based example</button><button id="axisMoveA">Move reference A along axis</button><button id="axisReset">Reset example</button></div><p id="axisError" class="error" role="status"></p><div id="axisSummary" class="result-summary" aria-live="polite"></div></article><article class="panel"><h3>Axis moment, step by step</h3><div class="symbol-help">Tap an <strong>underlined symbol</strong> for its meaning here.</div><div id="axisSteps"></div></article></div><article class="panel concept"><h3>A moment vector and an axis moment are different quantities.</h3><div class="concept-grid"><p><strong>Choose a positive axis.</strong><br>A→B defines u. The scalar’s sign describes the right-hand-rule rotational sense about that direction.</p><p><strong>Project only after calculating the moment.</strong><br>Use a point on the axis for r. A moment about an arbitrary point off the axis must be translated before projection.</p><p><strong>Report what was asked.</strong><br>Maxis is signed; its magnitude is |Maxis|. Neither generally equals the magnitude of the full moment vector.</p></div></article><article id="axisPractice" class="panel position-practice"></article>`;
 function calculateAxis(s){return s.source==='force'?M.forceAxisMoment(s.A,s.B,s.P,s.F,s.reverse):M.axisMoment(s.A,s.B,s.M,s.reverse);}
 function axisSteps(s){
  const a=calculateAxis(s),raw=s.B.map((v,i)=>v-s.A[i]),positive=s.reverse?raw.map(v=>-v):raw;
  let output=E.row(1,'Normalize the positive axis','Unit direction of the specified axis',math(axisUnit()+mo('=')+fraction(E.text(s.reverse?'A − B':'B − A'),E.text('|B − A|')))+math(axisUnit()+mo('=')+E.vec(a.unit)),`The points must be <strong>distinct</strong>. Current positive direction: <strong>${s.reverse?'B→A':'A→B'}</strong>. Direction components: <strong>${E.tuple(positive)} m</strong>; length: <strong>${E.round(a.length)} m</strong>.`);
  if(s.source==='force'){
   const m=a.pointMoment,pairs=[[1,2],[2,0],[0,1]];
   output+=E.row(2,'Calculate the moment about A','Moment about a point on the axis',math(axisR()+mo('=')+E.text('P − A')+mo('=')+E.vec(m.r,'m'))+math(pointM()+mo('=')+axisR()+mo('×')+vector('F','forceMoment'))+pairs.map(([j,k],i)=>math(symbolMarkup('M'+E.axes[i],'axisM'+E.axes[i],'<msub><mi>M</mi><mi>'+E.axes[i]+'</mi></msub>')+mo('=')+mo('(')+E.num(m.r[j])+mo(')')+mo('(')+E.num(s.F[k])+mo(')')+mo('−')+mo('(')+E.num(m.r[k])+mo(')')+mo('(')+E.num(s.F[j])+mo(')')+mo('=')+E.num(m.components[i])+E.text(' N·m'))).join('')+math(pointM()+mo('=')+E.vec(a.components,'N·m')),'<strong>Reference point A lies on the specified axis.</strong> The position vector starts at A and ends on the force line. Use <strong>rAP × F</strong>.');
  }else output+=E.row(2,'Use the supplied moment vector','Given moment about a point on the axis',math(pointM()+mo('=')+E.vec(a.components,'N·m')),'The supplied moment must be <strong>about A or another point on this same axis</strong>. Its full magnitude is not automatically the axis moment magnitude.');
  output+=E.row(3,'Project onto the axis','Signed axis moment',math(axisScalar()+mo('=')+axisUnit()+mo('·')+pointM())+math(axisScalar()+mo('=')+a.unit.map((v,i)=>(i?mo('+'):'')+mo('(')+E.num(v)+mo(')')+mo('(')+E.num(a.components[i])+mo(')')).join('')+mo('=')+E.num(a.scalar)+E.text(' N·m')),`<strong>Multiply matching components and add.</strong> ${Math.abs(a.scalar)<1e-9?'There is <strong>no twisting moment about this axis</strong>.':a.scalar>0?'Positive: <strong>right-hand-rule rotation about the positive axis</strong>.':'Negative: <strong>rotation opposite the positive-axis convention</strong>.'}`);
  output+=E.row(4,'Distinguish scalar, magnitude, and vector','Axis moment interpretation',math(mo('|')+axisScalar()+mo('|')+mo('=')+E.num(a.magnitude)+E.text(' N·m'))+math(taggedVector('M','∥','axisMomentParallel')+mo('=')+axisScalar()+axisUnit()+mo('=')+E.vec(a.parallel,'N·m')),`If asked for <strong>magnitude only</strong>, report <strong>${E.round(a.magnitude)} N·m</strong>. Reversing the axis changes the <strong>scalar sign</strong>, but preserves its magnitude and axial vector.`);return output;
 }
 function renderAxis(){try{
  const a=calculateAxis(axisState),span=Math.max(a.length,1),origin=axisState.A,unit=a.unit,items=[{start:axisState.A,end:axisState.B,color:'#8cbcff',label:'B / axis',dashed:true},{start:origin,end:origin.map((v,i)=>v+unit[i]*span*.7),color:'#efbd77',label:'+axis',arrow:true}];
  const magnitude=Math.hypot(...a.components);if(magnitude)items.push({start:origin,end:origin.map((v,i)=>v+a.components[i]/magnitude*span*.6),color:'#d3a0ee',label:'MA direction',arrow:true});if(a.magnitude)items.push({start:origin,end:origin.map((v,i)=>v+a.parallel[i]/a.magnitude*span*.5),color:'#b4f178',label:'M∥ direction',arrow:true});
  if(axisState.source==='force'){items.push({start:origin,end:axisState.P,color:'#617384',label:'P / rAP',dashed:true});const f=Math.hypot(...axisState.F);if(f)items.push({start:axisState.P,end:axisState.P.map((v,i)=>v+axisState.F[i]/f*span*.4),color:'#b4f178',label:'F direction',arrow:true});}
  E.diagram('axisDiagram',axisState.view,items);$('axisSteps').innerHTML=axisSteps(axisState);$('axisProblem').innerHTML=`Axis points: <strong>A = ${E.tuple(axisState.A)} m</strong>, <strong>B = ${E.tuple(axisState.B)} m</strong>. ${axisState.source==='given'?`Given <strong>MA = ${E.tuple(axisState.M)} N·m</strong> about A.`:`Force <strong>F = ${E.tuple(axisState.F)} N</strong> acts at <strong>P = ${E.tuple(axisState.P)} m</strong>.`} Find the moment about the <strong>${axisState.reverse?'B→A':'A→B'} positive axis</strong>.`;$('axisSummary').innerHTML=`<div><small>SIGNED AXIS MOMENT</small>${E.round(a.scalar)} N·m</div><div><small>MAGNITUDE</small>${E.round(a.magnitude)} N·m</div>`;$('axisError').textContent='';
 }catch(e){$('axisError').textContent=e.message;$('axisSteps').innerHTML='';$('axisSummary').innerHTML='';$('axisDiagram').innerHTML='';}}
 function syncAxis(){for(const key of ['A','B','M','P','F'])E.sync('axis'+key,axisState[key]);$('axisSource').value=axisState.source;$('axisView').value=axisState.view;$('axisGivenInputs').hidden=axisState.source!=='given';$('axisForceInputs').hidden=axisState.source!=='force';$('axisMoveA').disabled=axisState.source!=='force';}
 for(const key of ['A','B','M','P','F'])E.axes.forEach((_,i)=>$('axis'+key+i).addEventListener('input',()=>{try{const keys=axisState.source==='given'?['A','B','M']:['A','B','P','F'],values=E.read(keys.map(k=>'axis'+k));keys.forEach((k,j)=>axisState[k]=values[j]);renderAxis();}catch(e){$('axisError').textContent=e.message;}}));
 $('axisSource').onchange=()=>{axisState.source=$('axisSource').value;syncAxis();renderAxis();};$('axisView').onchange=()=>{axisState.view=$('axisView').value;renderAxis();};$('axisReverse').onclick=()=>{axisState.reverse=!axisState.reverse;renderAxis();};$('axisReset').onclick=()=>{axisState={A:[0,0,0],B:[3,4,0],M:[0,180,0],P:[2,1,0],F:[0,100,0],reverse:false,source:'given',view:'iso'};syncAxis();renderAxis();};$('axisForceExample').onclick=()=>{axisState={A:[0,0,0],B:[0,0,2],M:[0,180,0],P:[2,1,0],F:[0,100,0],reverse:false,source:'force',view:'iso'};syncAxis();renderAxis();};
 $('axisMoveA').onclick=()=>{if(axisState.source!=='force')return;try{const a=calculateAxis(axisState),shift=a.unit.map(v=>v*.5),nextA=axisState.A.map((v,i)=>v+shift[i]),nextB=axisState.B.map((v,i)=>v+shift[i]);if([...nextA,...nextB].some(v=>Math.abs(v)>10000))throw Error('Moving the reference would exceed input bounds.');axisState.A=nextA;axisState.B=nextB;syncAxis();renderAxis();}catch(e){$('axisError').textContent=e.message;}};
 const axisCases=[{name:'Given moment along an oblique axis',A:[0,0,0],B:[3,4,0],M:[0,180,0],source:'given'},{name:'Negative axis moment',A:[0,0,0],B:[3,4,0],M:[0,-180,0],source:'given'},{name:'Moment perpendicular to axis',A:[0,0,0],B:[3,4,0],M:[0,0,200],source:'given'},{name:'Force-based 3D axis moment',A:[1,1,1],B:[3,2,3],P:[3,4,5],F:[100,-50,200],source:'force'}].map(c=>({...c,reverse:false,problem:`For <strong>A = ${E.tuple(c.A)} m</strong> and <strong>B = ${E.tuple(c.B)} m</strong>, find the <strong>signed A→B axis moment</strong> and its <strong>magnitude</strong>. ${c.source==='given'?`The given moment about A is <strong>${E.tuple(c.M)} N·m</strong>.`:`A force <strong>${E.tuple(c.F)} N</strong> acts at <strong>P = ${E.tuple(c.P)} m</strong>.`}`,feedback:'Use the axis unit vector. Calculate the moment about A first if needed, then dot it with uAB. Keep the scalar sign; report absolute value for magnitude. Tolerance: 0.1 N·m.'}));
 E.practice({id:'axisPractice',title:'Find the moment about the rod.',cases:axisCases,targets:c=>{const a=calculateAxis(c);return [{label:'Signed Maxis (N·m)',value:a.scalar,tolerance:.1},{label:'|Maxis| (N·m)',value:a.magnitude,tolerance:.1}];},solution:axisSteps,hints:['Form uAB = (B − A)/|B − A|. Axis direction alone is not a unit vector.','If only a force is given, calculate MA = (P − A) × F before projection.','Dot the full moment with uAB. The signed result can be negative; its magnitude cannot.']});syncAxis();renderAxis();
 let coupleState={P:[2,0,0],Q:[0,0,0],F:[0,100,0],O:[0,0,0],view:'xy'};
 $('coupleLesson').innerHTML=`<div class="lab-grid"><article class="panel"><div class="panel-heading"><h3>Equal and opposite force pair</h3><span class="live">● LIVE</span></div><p id="coupleProblem" class="position-problem"></p>${viewSelect('coupleView')}<svg id="coupleDiagram" viewBox="0 0 600 400" role="img" aria-label="Equal opposite force pair, force lines, perpendicular spacing and couple direction"></svg><p class="projection-note">Force arrows show directions with <strong>equal illustrative lengths</strong>. Geometry shares a metre scale; the couple arrow shows direction only. Screen measurements are projected.</p><div class="coordinate-controls">${E.fields('coupleP','Point P: +F acts here','m',coupleState.P)}${E.fields('coupleQ','Point Q: −F acts here','m',coupleState.Q)}</div><div class="coordinate-controls">${E.fields('coupleF','Positive force F','N',coupleState.F)}${E.fields('coupleO','Moment-sum reference O','m',coupleState.O)}</div><p class="projection-note">The second force is automatically <strong>−F</strong>, enforcing equal magnitude and opposite direction.</p><div class="actions"><button id="coupleMoveO">Change reference point O</button><button id="coupleSwap">Swap force locations</button><button id="couple3D">3D example</button><button id="coupleReset">Reset example</button></div><p id="coupleError" class="error" role="status"></p><div id="coupleSummary" class="result-summary" aria-live="polite"></div></article><article class="panel"><h3>Couple, step by step</h3><div class="symbol-help">Tap an <strong>underlined symbol</strong> for its meaning here.</div><div id="coupleSteps"></div></article></div><article class="panel concept"><h3>Zero resultant force does not mean zero moment.</h3><div class="concept-grid"><p><strong>Couple conditions.</strong><br>The forces have equal magnitude, opposite direction, and parallel lines. Different force lines create a nonzero moment.</p><p><strong>A free moment vector.</strong><br>The separate moments depend on O, but their sum does not. You can represent the same couple anywhere on a rigid body.</p><p><strong>Use one force magnitude.</strong><br>|Mc| = Fd, not 2Fd. Use the perpendicular spacing between the parallel force lines, not automatically |P − Q|.</p></div></article><article id="couplePractice" class="panel position-practice"></article>`;
 function coupleSteps(s){
  const c=M.couple(s.P,s.Q,s.F,s.O),pairs=[[1,2],[2,0],[0,1]],sum=c.positiveMoment.map((v,i)=>v+c.negativeMoment[i]);
  let output=E.row(1,'Check the force pair','Equal and opposite forces',math(vector('R','coupleResultant')+mo('=')+force()+mo('+')+mo('(')+mo('−')+force()+mo(')')+mo('=')+E.vec(c.totalForce,'N')),'The second force is <strong>exactly −F</strong>. Net force is <strong>zero</strong>. A nonzero couple requires <strong>distinct parallel lines of action</strong>.');
  output+=E.row(2,'Choose the separation in the correct direction','Separation from negative to positive force',math(separation()+mo('=')+mi('P','couplePointP')+mo('−')+mi('Q','couplePointQ')+mo('=')+E.vec(c.separation,'m')),'Use the separation <strong>from −F at Q to +F at P</strong> with the positive force F.');
  output+=E.row(3,'Calculate the couple vector','Couple cross product',math(coupleM()+mo('=')+separation()+mo('×')+force())+pairs.map(([j,k],i)=>math(E.text('M'+E.axes[i])+mo('=')+mo('(')+E.num(c.separation[j])+mo(')')+mo('(')+E.num(s.F[k])+mo(')')+mo('−')+mo('(')+E.num(c.separation[k])+mo(')')+mo('(')+E.num(s.F[j])+mo(')')+mo('=')+E.num(c.components[i])+E.text(' N·m'))).join('')+math(coupleM()+mo('=')+E.vec(c.components,'N·m')),'Use the <strong>right-hand rule</strong> from separation toward F. Swapping the force locations reverses the couple vector.');
  output+=E.row(4,'Find magnitude and line spacing','Couple magnitude and perpendicular spacing',math(mo('|')+coupleM()+mo('|')+mo('=')+E.num(c.magnitude)+E.text(' N·m'))+(c.arm===null?'Zero force: the couple moment is zero; force-line spacing is undefined.':math(arm()+mo('=')+fraction(mo('|')+coupleM()+mo('|'),mo('|')+force()+mo('|'))+mo('=')+fraction(E.num(c.magnitude),E.num(c.forceMagnitude))+mo('=')+E.num(c.arm)+E.text(' m'))),c.forceMagnitude?`Check: <strong>${E.round(c.forceMagnitude)} N × ${E.round(c.arm)} m = ${E.round(c.magnitude)} N·m</strong>. Use <strong>one force magnitude</strong>. ${c.magnitude===0?'<strong>The force lines coincide, so there is no nonzero couple moment.</strong>':''}`:'With zero forces, there is no turning effect.');
  output+=E.row(5,'Verify reference-point independence','Sum of individual moments about O',math(taggedVector('M','O,+F','couplePositiveMoment')+mo('=')+E.vec(c.positiveMoment,'N·m'))+math(taggedVector('M','O,−F','coupleNegativeMoment')+mo('=')+E.vec(c.negativeMoment,'N·m'))+math(E.text('Sum about ')+mi('O','coupleReference')+mo('=')+E.vec(sum,'N·m'))+math(E.text('Sum about ')+mi('O','coupleReference')+mo('=')+coupleM()),`Here <strong>O = ${E.tuple(s.O)} m</strong>. The individual moments change when O moves; their <strong>sum is unchanged</strong>. Try changing the reference point.`);return output;
 }
 function renderCouple(){const c=M.couple(coupleState.P,coupleState.Q,coupleState.F,coupleState.O),span=Math.max(Math.hypot(...c.separation),1),items=[{start:coupleState.Q,end:coupleState.P,color:'#8cbcff',label:'rQP / P',dashed:true},{start:coupleState.O,end:coupleState.O,color:'#94a3b8',label:'reference O'}];
  if(c.forceMagnitude){const unit=coupleState.F.map(v=>v/c.forceMagnitude),foot=M.moment(coupleState.Q,coupleState.P,coupleState.F).foot;items.push({start:coupleState.P.map((v,i)=>v-unit[i]*span*.7),end:coupleState.P.map((v,i)=>v+unit[i]*span*.7),color:'#617384',label:'+F line',dashed:true},{start:coupleState.Q.map((v,i)=>v-unit[i]*span*.7),end:coupleState.Q.map((v,i)=>v+unit[i]*span*.7),color:'#617384',label:'−F line',dashed:true},{start:coupleState.P,end:coupleState.P.map((v,i)=>v+unit[i]*span*.5),color:'#b4f178',label:'+F',arrow:true},{start:coupleState.Q,end:coupleState.Q.map((v,i)=>v-unit[i]*span*.5),color:'#efbd77',label:'−F',arrow:true},{start:coupleState.Q,end:foot,color:'#efbd77',label:'d',dashed:true});}
  if(c.magnitude)items.push({start:coupleState.O,end:coupleState.O.map((v,i)=>v+c.components[i]/c.magnitude*span*.5),color:'#d3a0ee',label:'Mc direction',arrow:true});E.diagram('coupleDiagram',coupleState.view,items);$('coupleSteps').innerHTML=coupleSteps(coupleState);$('coupleProblem').innerHTML=`<strong>+F = ${E.tuple(coupleState.F)} N</strong> acts at <strong>P = ${E.tuple(coupleState.P)} m</strong>. <strong>−F = ${E.tuple(coupleState.F.map(v=>-v))} N</strong> acts at <strong>Q = ${E.tuple(coupleState.Q)} m</strong>. Find the couple moment.`;$('coupleSummary').innerHTML=`<div><small>COUPLE MAGNITUDE</small>${E.round(c.magnitude)} N·m</div><div><small>NET FORCE</small>0 N</div>`;$('coupleError').textContent='';}
 function syncCouple(){for(const key of ['P','Q','F','O'])E.sync('couple'+key,coupleState[key]);$('coupleView').value=coupleState.view;}
 for(const key of ['P','Q','F','O'])E.axes.forEach((_,i)=>$('couple'+key+i).addEventListener('input',()=>{try{const keys=['P','Q','F','O'],values=E.read(keys.map(k=>'couple'+k));keys.forEach((k,j)=>coupleState[k]=values[j]);renderCouple();}catch(e){$('coupleError').textContent=e.message;}}));
 $('coupleView').onchange=()=>{coupleState.view=$('coupleView').value;renderCouple();};$('coupleMoveO').onclick=()=>{const next=coupleState.O.map((v,i)=>v+[1,-2,3][i]);if(next.some(v=>Math.abs(v)>10000)){$('coupleError').textContent='Moving O would exceed input bounds.';return;}coupleState.O=next;syncCouple();renderCouple();};$('coupleSwap').onclick=()=>{[coupleState.P,coupleState.Q]=[coupleState.Q,coupleState.P];syncCouple();renderCouple();};$('coupleReset').onclick=()=>{coupleState={P:[2,0,0],Q:[0,0,0],F:[0,100,0],O:[0,0,0],view:'xy'};syncCouple();renderCouple();};$('couple3D').onclick=()=>{coupleState={P:[3,2,1],Q:[1,-1,-3],F:[100,-50,200],O:[0,0,0],view:'iso'};syncCouple();renderCouple();};
 const coupleCases=[{name:'Planar couple',P:[2,0,0],Q:[0,0,0],F:[0,100,0],O:[0,0,0]},{name:'Reversed couple',P:[0,0,0],Q:[2,0,0],F:[0,100,0],O:[0,0,0]},{name:'Oblique point spacing',P:[2,3,0],Q:[0,0,0],F:[0,100,0],O:[4,-2,1]},{name:'3D couple',P:[3,2,1],Q:[1,-1,-3],F:[100,-50,200],O:[0,0,0]}].map(c=>({...c,problem:`<strong>+F = ${E.tuple(c.F)} N</strong> acts at <strong>P = ${E.tuple(c.P)} m</strong>, and <strong>−F</strong> acts at <strong>Q = ${E.tuple(c.Q)} m</strong>. Find the <strong>couple moment components</strong> and <strong>perpendicular line spacing</strong>.`,feedback:'Use (P − Q) × F, with F at P. The spacing is |Mc|/|F|, not automatically |P − Q|. Tolerances: 0.1 N·m and 0.01 m.'}));
 E.practice({id:'couplePractice',title:'Find the couple and its line spacing.',cases:coupleCases,targets:c=>{const result=M.couple(c.P,c.Q,c.F,c.O);return [...result.components.map((v,i)=>({label:'Mc'+E.axes[i]+' (N·m)',value:v,tolerance:.1})),{label:'Perpendicular d (m)',value:result.arm,tolerance:.01}];},solution:coupleSteps,hints:['Identify which point carries +F. The separation must run from −F to +F.','Calculate (P − Q) × F. You do not multiply the force magnitude by 2.','Find d = |Mc| / |F|. A coordinate component parallel to the force does not increase the line spacing.']});syncCouple();renderCouple();
})();
